// Core tests: the 32 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, identity and formatting
// cases from the SPEC. Every expected value below was computed by hand
// from the SPEC's rules; the hand derivations are listed in
// AUTHOR-CHECK.md.

import assert from "node:assert/strict";
import test from "node:test";
import {
  REFERENCE_TABLE,
  formatMoney,
  formatPercent,
  roundHalfUpDiv,
  roundRatio,
  run,
} from "../public/js/core/markup-margin.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

const reportBase = {
  mode: "report",
  cost: "80.00",
  price: "100.00",
  markupPercent: null,
  marginPercent: null,
};

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("rounding primitives: exact halves round up / away from zero", () => {
  assert.equal(roundHalfUpDiv(5n, 2n), 3n);
  assert.equal(roundHalfUpDiv(4n, 2n), 2n);
  assert.equal(roundHalfUpDiv(1n, 2n), 1n);
  assert.equal(roundHalfUpDiv(0n, 7n), 0n);
  assert.equal(roundRatio(25n, 10n), 3n);
  assert.equal(roundRatio(-25n, 10n), -3n);
  assert.equal(roundRatio(-5n, 2n), -3n);
  assert.equal(roundRatio(0n, 7n), 0n);
  assert.equal(roundRatio(24n, 10n), 2n);
});

test("hand-derived report: 10.00 / 12.50 gives markup 25.00% and margin 20.00%", () => {
  const outcome = run({ ...reportBase, cost: "10.00", price: "12.50" });
  assert.deepEqual(outcome, {
    ok: true,
    result: {
      mode: "report",
      costCents: 1000,
      priceCents: 1250,
      profitCents: 250,
      markupHundredths: 2500,
      marginHundredths: 2000,
      belowCost: false,
    },
  });
});

test("hand-derived solve-markup: 0.001% on 100.00 rounds the price down to cost", () => {
  // price = 10000 * 100001 / 100000 = 10000.1 -> 10000; profit 0.
  const outcome = run({
    mode: "solve-markup",
    cost: "100.00",
    price: null,
    markupPercent: "0.001",
    marginPercent: null,
  });
  assert.deepEqual(outcome, {
    ok: true,
    result: {
      mode: "solve-markup",
      costCents: 10000,
      markupPercentMilli: 1,
      priceCents: 10000,
      profitCents: 0,
      marginHundredths: 0,
    },
  });
});

test("hand-derived solve-margin: 0.01 at 99.999% gives price 1000.00 and markup 9999900.00%", () => {
  // price = 1 * 100000 / 1 = 100000; profit 99999;
  // markup = 99999 * 10000 / 1 = 999990000 hundredths.
  const outcome = run({
    mode: "solve-margin",
    cost: "0.01",
    price: null,
    markupPercent: null,
    marginPercent: "99.999",
  });
  assert.deepEqual(outcome, {
    ok: true,
    result: {
      mode: "solve-margin",
      costCents: 1,
      marginPercentMilli: 99999,
      priceCents: 100000,
      profitCents: 99999,
      markupHundredths: 999990000,
    },
  });
});

test("hand-derived solve-markup at the percent cap: 0.01 at 99999.999% gives price 10.01", () => {
  // price = 1 * (100000 + 99999999) / 100000 = 1000.99999 -> 1001;
  // profit 1000; margin = 1000 * 10000 / 1001 = 9990.0099... -> 9990.
  const outcome = run({
    mode: "solve-markup",
    cost: "0.01",
    price: null,
    markupPercent: "99999.999",
    marginPercent: null,
  });
  assert.deepEqual(outcome, {
    ok: true,
    result: {
      mode: "solve-markup",
      costCents: 1,
      markupPercentMilli: 99999999,
      priceCents: 1001,
      profitCents: 1000,
      marginHundredths: 9990,
    },
  });
});

test("boundaries: legal endpoints succeed, just over the cap is RANGE", () => {
  assert.equal(run({ ...reportBase, cost: "0.01", price: "0.01" }).ok, true);
  assert.equal(run({ ...reportBase, cost: "999999.99", price: "999999.99" }).ok, true);
  assert.equal(
    run({ mode: "solve-markup", cost: "0.01", price: null, markupPercent: "0", marginPercent: null }).ok,
    true,
  );
  assert.deepEqual(errorOf({ ...reportBase, cost: "1000000.00" }), {
    code: "RANGE",
    field: "cost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, price: "1000000.00" }), {
    code: "RANGE",
    field: "price",
    row: null,
  });
  assert.deepEqual(
    errorOf({ mode: "solve-markup", cost: "80.00", price: null, markupPercent: "100000", marginPercent: null }),
    { code: "RANGE", field: "markupPercent", row: null },
  );
});

test("NO_SOLUTION is distinct from RANGE: 100.000% has no solution, 99999.999% is RANGE only via the price cap", () => {
  assert.deepEqual(
    errorOf({ mode: "solve-margin", cost: "80.00", price: null, markupPercent: null, marginPercent: "100.000" }),
    { code: "NO_SOLUTION", field: "marginPercent", row: null },
  );
  // 99.999% is a legal margin (milli 99999 < 100000); the solved price
  // 8000 * 100000 / 1 = 800,000,000 cents is over the price cap, so
  // this is RANGE on marginPercent.
  assert.deepEqual(
    errorOf({ mode: "solve-margin", cost: "80.00", price: null, markupPercent: null, marginPercent: "99.999" }),
    { code: "RANGE", field: "marginPercent", row: null },
  );
});

test("capacity and surrogate: INPUT_LIMIT before UNICODE before EMPTY before grammar", () => {
  assert.deepEqual(errorOf({ ...reportBase, mode: "report-report1" }), {
    code: "INPUT_LIMIT",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, cost: "12345678901" }), {
    code: "INPUT_LIMIT",
    field: "cost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, cost: "\uD800" }), {
    code: "UNICODE",
    field: "cost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, mode: "\uD800" }), {
    code: "UNICODE",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, cost: "" }), {
    code: "EMPTY",
    field: "cost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, price: "" }), {
    code: "EMPTY",
    field: "price",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, mode: "" }), {
    code: "EMPTY",
    field: "mode",
    row: null,
  });
});

test("grammar: leading zeros, signs, commas, extra decimals and non-ASCII digits are DECIMAL_FORMAT", () => {
  for (const bad of ["01", "00.5", "-5", "+5", "1,000", "10.005", "0.001", "10.", ".5", "１０"]) {
    assert.deepEqual(errorOf({ ...reportBase, cost: bad }), {
      code: "DECIMAL_FORMAT",
      field: "cost",
      row: null,
    });
  }
  for (const bad of ["00.5", "33.3333", "-1", "1e2", "５"]) {
    assert.deepEqual(
      errorOf({ mode: "solve-markup", cost: "10.00", price: null, markupPercent: bad, marginPercent: null }),
      { code: "DECIMAL_FORMAT", field: "markupPercent", row: null },
    );
  }
  // "0", "0.0" and "0.00" are grammatical for money; "0.000" for percent.
  assert.equal(run({ ...reportBase, price: "0.0" }).ok, true);
  assert.equal(
    run({ mode: "solve-margin", cost: "10.00", price: null, markupPercent: null, marginPercent: "0.000" }).ok,
    true,
  );
});

test("mode consistency is SCHEMA and is checked before cost validation", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(
    errorOf({ mode: "solve-markup", cost: "80.00", price: "100.00", markupPercent: "25", marginPercent: null }),
    schema,
  );
  assert.deepEqual(
    errorOf({ mode: "solve-margin", cost: "80.00", price: null, markupPercent: "25", marginPercent: "20" }),
    schema,
  );
  assert.deepEqual(errorOf({ ...reportBase, marginPercent: "20" }), schema);
  // Even with an out-of-range cost, the consistency failure wins.
  assert.deepEqual(
    errorOf({ mode: "report", cost: "0", price: null, markupPercent: "25", marginPercent: null }),
    schema,
  );
});

test("the first error in the fixed order wins", () => {
  assert.deepEqual(errorOf({ ...reportBase, mode: "REPORT", cost: "0" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, cost: "0", price: "bad" }), {
    code: "RANGE",
    field: "cost",
    row: null,
  });
  assert.deepEqual(errorOf({ ...reportBase, cost: "10.005", price: "bad" }), {
    code: "DECIMAL_FORMAT",
    field: "cost",
    row: null,
  });
});

test("schema: extra key, missing key, wrong type, array, null, accessor and symbol key are all SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ ...reportBase, extra: "1" }), schema);
  const missing = { ...reportBase };
  delete missing.price;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...reportBase, cost: 80 }), schema);
  assert.deepEqual(errorOf({ ...reportBase, price: 100 }), schema);
  assert.deepEqual(errorOf({ ...reportBase, markupPercent: 25 }), schema);
  assert.deepEqual(errorOf({ ...reportBase, mode: null }), schema);
  assert.deepEqual(errorOf(["report"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("report"), schema);
  const withGetter = { ...reportBase };
  Object.defineProperty(withGetter, "cost", {
    enumerable: true,
    get() {
      return "80.00";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  const withSymbol = { ...reportBase, [Symbol("extra")]: "1" };
  assert.deepEqual(errorOf(withSymbol), schema);
  const stringObject = { ...reportBase };
  stringObject.cost = new String("80.00");
  assert.deepEqual(errorOf(stringObject), schema);
});

test("reference table: every row matches markup = margin / (100 - margin), rounded to two decimals", () => {
  assert.equal(REFERENCE_TABLE.length, 13);
  // Independent recomputation with plain BigInt half-up rounding.
  for (const row of REFERENCE_TABLE) {
    const m = BigInt(row.marginPercent);
    const numerator = m * 10000n;
    const denominator = 100n - m;
    const q = numerator / denominator;
    const r = numerator % denominator;
    const rounded = 2n * r >= denominator ? q + 1n : q;
    assert.equal(BigInt(row.markupHundredths), rounded, `margin ${row.marginPercent}%`);
  }
  assert.deepEqual(REFERENCE_TABLE[0], { marginPercent: 0, markupHundredths: 0 });
  assert.deepEqual(REFERENCE_TABLE[12], { marginPercent: 95, markupHundredths: 190000 });
});

test("identities: plugging a solved price back into report reproduces the other rate", () => {
  // solve-markup 33.333% on 10.00 -> price 13.33; report on that price
  // must give margin 2498 (the fixture's derived rate).
  const solved = run({
    mode: "solve-markup",
    cost: "10.00",
    price: null,
    markupPercent: "33.333",
    marginPercent: null,
  });
  assert.equal(solved.ok, true);
  const back = run({
    mode: "report",
    cost: "10.00",
    price: formatMoney(solved.result.priceCents),
    markupPercent: null,
    marginPercent: null,
  });
  assert.equal(back.ok, true);
  assert.equal(back.result.marginHundredths, solved.result.marginHundredths);
  // The markup recomputed from the rounded price 13.33 is
  // 333 / 1000 = 33.30% (3330), not the 33.333% target: the derived
  // rate comes from the rounded price, exactly as the SPEC pins.
  assert.equal(back.result.markupHundredths, 3330);
  // solve-margin 33.333% on 10.00 -> price 15.00; report on that price
  // must give markup 5000.
  const solvedMargin = run({
    mode: "solve-margin",
    cost: "10.00",
    price: null,
    markupPercent: null,
    marginPercent: "33.333",
  });
  assert.equal(solvedMargin.ok, true);
  const backMargin = run({
    mode: "report",
    cost: "10.00",
    price: formatMoney(solvedMargin.result.priceCents),
    markupPercent: null,
    marginPercent: null,
  });
  assert.equal(backMargin.ok, true);
  assert.equal(backMargin.result.markupHundredths, solvedMargin.result.markupHundredths);
});

test("the core does not mutate its input", () => {
  const input = { ...reportBase };
  const snapshot = JSON.stringify(input);
  const outcome = run(input);
  assert.equal(outcome.ok, true);
  assert.equal(JSON.stringify(input), snapshot);
  const bad = { ...reportBase, cost: "0" };
  const badSnapshot = JSON.stringify(bad);
  assert.equal(run(bad).ok, false);
  assert.equal(JSON.stringify(bad), badSnapshot);
});

test("display formatting: money two decimals with sign, percent two decimals with %", () => {
  assert.equal(formatMoney(0), "0.00");
  assert.equal(formatMoney(5), "0.05");
  assert.equal(formatMoney(-2001), "-20.01");
  assert.equal(formatMoney(10000), "100.00");
  assert.equal(formatMoney(99999999), "999999.99");
  assert.equal(formatPercent(2500), "25.00%");
  assert.equal(formatPercent(-2502), "-25.02%");
  assert.equal(formatPercent(0), "0.00%");
  assert.equal(formatPercent(10000), "100.00%");
  assert.equal(formatPercent(999999980000), "9999999800.00%");
  assert.equal(formatPercent(null), null);
});
